window.ATLAS.addDetails("life.edges",{"edges":{
"action-potential:feedback":{"type":"connection","label":{"zh":"Na⁺ 通道的正反馈","en":"Positive feedback in the Na⁺ channels"},"reason":{"zh":"电位一升，更多电压门控 Na⁺ 通道打开，Na⁺ 进得更多、电位升得更快——这是一条正反馈，所以过了阈值就停不下来，只能冲到顶，这正是“全或无”的来源。","en":"A rise in voltage opens more voltage-gated Na⁺ channels, letting in more Na⁺ and raising the voltage faster — positive feedback, which is why once past threshold the spike cannot stop halfway: the origin of “all-or-none”."},"source":"../biology/body/action-potential/#step1"},
"cell-structure:dna-replication":{"type":"application","label":{"zh":"核里的信息要靠复制传下去","en":"The nucleus's information passes on through replication"},"reason":{"zh":"细胞核管着遗传信息，信息要进下一代就得复制——细胞页的“指挥中心”，在复制页变成“复制什么、怎么保真”。","en":"The nucleus holds the genetic information, and for it to reach the next generation it must be copied — the cell page's 'command center' becomes, on the replication page, 'what is copied and how faithfully'."},"source":"../biology/cells/cell-structure/#step1"},
"cell-structure:membrane-transport":{"type":"foundation","label":{"zh":"细胞膜是这道门","en":"The cell membrane is the gate"},"reason":{"zh":"细胞靠一层膜把内外分开；膜对不同物质的通透性不同，内外浓度才能维持差异，也才谈得上谁进谁出。","en":"A cell keeps inside and outside apart with a membrane; because the membrane lets different substances through to different degrees, inside and outside can hold different concentrations, and it makes sense to ask what goes in and what comes out."},"source":"../biology/cells/membrane-transport/"},
"cell-structure:molecules-atoms":{"type":"foundation","label":{"zh":"细胞是分子搭成的车间","en":"Cells are workshops built from molecules"},"reason":{"zh":"从叶子逐级放大到细胞，是同一条尺度链的下一级：细胞比分子大得多，里面的工位全由分子搭成。","en":"Zooming from a leaf down to a cell is the next level of the same scale chain: cells are far larger than molecules, and every workstation inside is built from them."},"source":"../biology/cells/cell-structure/#step0"},
"cell-structure:photosynthesis":{"type":"application","label":{"zh":"叶绿体是光合作用的车间","en":"The chloroplast is photosynthesis's workshop"},"reason":{"zh":"细胞页里叶绿体只是“光合的工位”，光合页讲它怎样把光变成糖——结构与功能在两页接上，植物细胞多出叶绿体正为此准备。","en":"On the cell page the chloroplast is just 'the photosynthesis workstation'; the photosynthesis page shows how it turns light into sugar — structure meets function across the two pages, and plant cells carry chloroplasts for exactly this."},"source":"../biology/cells/cell-structure/#step2"},
"electric-fields:resting-potential":{"type":"foundation","label":{"zh":"膜两侧的电势差","en":"A potential difference across the membrane"},"reason":{"zh":"膜内外正负离子分布不均，就在薄薄一层膜两侧形成电势差；静息电位就是用伏特（毫伏）来量的这一段电势差。","en":"Unequal positive and negative ions on the two sides of a thin membrane create a potential difference across it; the resting potential is that difference, measured in volts (millivolts)."},"source":"../biology/body/neuroscience-basics/#step0"},
"exp-log:epidemic-r0":{"type":"foundation","label":{"zh":"一代乘一个 R","en":"Multiply by R each generation"},"reason":{"zh":"每个病例传给 R 个人，开头病例数就一代乘一次 R：R > 1 时指数增长，R < 1 时指数衰减。页面的 SIR 曲线开头正是这段指数增长，之后易感者耗尽才把它压弯。","en":"Each case passes it to R others, so early on case numbers are multiplied by R every generation: exponential growth when R > 1, exponential decay when R < 1. The page’s SIR curve starts with exactly that exponential rise, until running out of susceptibles bends it over."},"source":"../biology/body/public-health/#step0"},
"exp-log:logistic-growth":{"type":"foundation","label":{"zh":"没有 K 时就是指数增长","en":"Without K it is exponential growth"},"reason":{"zh":"N(t) = N₀·e^(rt) 是逻辑斯蒂曲线的起点：N 远小于 K 时两条线重合，翻倍时间是 ln2 / r；K 只是把这条指数线压弯。","en":"N(t) = N₀·e^(rt) is where the logistic curve starts: while N is far below K the two lines coincide and the doubling time is ln2 / r; K only bends that exponential."},"source":"../biology/ecology/logistic-growth/#step1"},
"food-web:energy-pyramid":{"type":"connection","label":{"zh":"能量逐级递减","en":"Energy shrinks level by level"},"reason":{"zh":"每上一个营养级能量只留下传递效率那一小部分，所以金字塔越往上越窄，顶级捕食者数量最少。","en":"Each trophic level up keeps only the transfer-efficiency fraction of the energy, so the pyramid narrows upward and top predators are the fewest."},"source":"../biology/ecology/food-web/#step1"},
"logistic-growth:chaos-threebody":{"type":"connection","label":{"zh":"r 太大时离散模型走向混沌","en":"Push r too far and the discrete model turns chaotic"},"reason":{"zh":"逐代迭代 N ← N + rN(1 − N/K) 在 r > 2 时不再趋稳：先 2 周期、4 周期，r 约 2.57 以后进入混沌，初值差一点结果就天差地别——和三体一样，确定规则也能不可预测。","en":"The generation-by-generation update N ← N + rN(1 − N/K) stops settling once r > 2: first period 2, then 4, and past r ≈ 2.57 it is chaotic, with tiny differences in the start blowing up — like the three-body problem, a deterministic rule that cannot be predicted."},"source":"../biology/ecology/logistic-growth/#step4"},
"logistic-growth:predator-prey":{"type":"foundation","label":{"zh":"在 K 的反馈旁边加一个捕食者","en":"Add a predator next to the K feedback"},"reason":{"zh":"捕食者—猎物模型以猎物自己的逻辑斯蒂增长为底，再加上被吃掉的那一项；没有捕食者时，猎物就停在 K。","en":"The predator–prey model starts from the prey’s own logistic growth and adds a term for being eaten; with no predator the prey simply settles at K."},"source":"../biology/ecology/population-ecology/#step2"},
"membrane-transport:resting-potential":{"type":"foundation","label":{"zh":"离子梯度是静息电位的本钱","en":"Ion gradients are what the resting potential spends"},"reason":{"zh":"钠钾泵耗能把 K⁺ 泵进、Na⁺ 泵出，建立膜内外的离子浓度差；K⁺ 顺着浓度差从漏通道漏出，膜内就变负，这就是静息电位。","en":"The sodium–potassium pump spends energy moving K⁺ in and Na⁺ out, building concentration differences across the membrane; K⁺ leaking back out through its channels leaves the inside negative — the resting potential."},"source":"../biology/body/neuroscience-basics/#step0"},
"ode-phase-portraits:predator-prey":{"type":"representation","label":{"zh":"把两条时间曲线画成一个圈","en":"Two time curves drawn as one loop"},"reason":{"zh":"以猎物数为横轴、捕食者数为纵轴，此起彼伏的两条时间曲线就成了相平面上绕平衡点的闭圈；加上拥挤项（即 K），闭圈变成向内收的螺旋。","en":"Put prey on one axis and predators on the other and the two alternating time curves become a closed loop around the equilibrium in the phase plane; add a crowding term (K) and the loop becomes an inward spiral."},"source":"../math/calculus/ode-phase-portraits/#step2"},
"particles-states:membrane-transport":{"type":"foundation","label":{"zh":"扩散来自分子的随机运动","en":"Diffusion comes from random molecular motion"},"reason":{"zh":"分子一直在乱动，单个分子往哪边跑都可能；只是浓度高的一侧分子更多，统计上穿过去的更多，净通量才顺着浓度差。","en":"Molecules are always jostling, and any single one may go either way; there are simply more on the crowded side, so statistically more cross from there, and the net flux runs down the gradient."},"source":"../biology/cells/membrane-transport/"},
"photosynthesis:carbon-cycle":{"type":"application","label":{"zh":"叶片尺度 → 全球尺度","en":"Leaf scale → global scale"},"reason":{"zh":"光合作用每年把约 120 GtC 从空气移入植物，与呼吸大致相抵，是碳循环里最大的陆地流量。","en":"Photosynthesis moves about 120 GtC a year from air into plants, roughly cancelled by respiration, the largest land flux in the carbon cycle."},"source":"../earth/climate/carbon-cycle/#step1"},
"predator-prey:feedback":{"type":"connection","label":{"zh":"带延迟的负反馈会振荡","en":"Negative feedback with delay oscillates"},"reason":{"zh":"捕食者把猎物压下来，是一条负反馈；但它要过一段时间才跟上猎物的变化，延迟让调节总是过头，于是数量围着平衡点起伏——和控制系统里延迟导致振荡是同一个道理。","en":"Predators pushing prey down is negative feedback, but they respond only after a lag, so the correction always overshoots and numbers swing around the balance point — the same reason delay makes a control loop oscillate."},"source":"../biology/ecology/population-ecology/#step2"},
"resting-potential:action-potential":{"type":"foundation","label":{"zh":"从 −70 mV 出发","en":"Starting from −70 mV"},"reason":{"zh":"每个尖峰都从静息电位起跳、最后落回它附近；阈值也是相对静息电位而言，要推高十几毫伏才会触发。","en":"Every spike takes off from the resting potential and falls back near it; the threshold, too, is measured from rest — the voltage has to be pushed up by a dozen or so millivolts to trigger it."},"source":"../biology/body/action-potential/#step0"},
"working-memory-attention:signal-detection-theory":{"type":"connection","label":{"zh":"目标是信号，干扰物与它争道","en":"Targets are signal, distractors compete"},"reason":{"zh":"本页把注意当作带宽有限的通道：目标是要找的信号，干扰物同时涌入，干扰越多命中率越低。信号检测论是继续读这类任务的标准方法：它把“分不分得开”（d′）与“多愿意说有”（判据 c）分开，本页的模型只画出前一种方向。","en":"The page treats attention as a limited channel: targets are the signal you look for, distractors arrive alongside them, and hits fall as distractors rise. Signal detection theory is the standard way to read such a task further: it separates how well targets can be told apart (d′) from how readily one says “yes” (criterion c); the page models only the first."},"source":"../psychology/cognition/memory-attention/#step1"}
}});
